{
  "actions": [
    {
      "action": "Preserve product focus with a predictable fallback",
      "mechanism": "Track product and control identity across reordering; disappearing products send focus to the persistent results heading.",
      "implementation": "Key cards by product ID. Preserve the active control when retained. If removed while focused, focus the heading using tabindex=\"-1\"; otherwise never move focus.",
      "check": "Keyboard-test retained-item reordering and focused-item removal. Confirm the same control remains active or the heading receives focus; verify screen-reader output.",
      "risk": "Index-based keys or unconditional focus restoration can redirect users unexpectedly."
    },
    {
      "action": "Separate immediate counts from result rendering",
      "mechanism": "A persistent status distinguishes pending, completed, empty, and failed requests without waiting for all cards to render.",
      "implementation": "Show “Updating” during requests; label any previous count. Reject stale responses. Publish accepted totals immediately in visible text and a polite status outside the busy results container.",
      "check": "Measure count publication within one second of arrival. Test zero, failure, and reversed response order; verify loading never announces zero.",
      "risk": "Screen-reader speech may queue even when the count is available."
    },
    {
      "action": "Offer a compact view without reducing coverage",
      "mechanism": "A text-first view reduces scanning detail while preserving every matching product and access to full information.",
      "implementation": "Add keyboard-operable Grid/Compact buttons. Compact mode shows product names, prices, distinguishing variants, and detail links. Share result data and ordering; keep focus on the activated view button.",
      "check": "For 200 matches, compare product IDs across views: none missing. Keyboard-open details and verify view switching preserves filter state and count.",
      "risk": "Over-simplification can hide distinctions; retain variant labels rather than merging products."
    }
  ],
  "abstention_reason": ""
}
